unsafe struct S
{
    public fixed int x[10];
}

class  S1
{
    public readonly S field;
}

class Program
{
    unsafe static void Main()
    {
        S1 c = new S1();
        c.field.x[0] = 12;
        ref readonly int iro = ref c.field.x[0];
        ref int irw = ref c.field.x[0];
    }
}

